// ErrorResponseMessage represents sum type.
type ErrorResponseMessage struct {
	Type         ErrorResponseMessageType // switch on this field
	ErrorMessage ErrorMessage
	String       string
}

// ErrorResponseMessageType is oneOf type of ErrorResponseMessage.
type ErrorResponseMessageType string

// Possible values for ErrorResponseMessageType.
const (
	ErrorMessageErrorResponseMessage ErrorResponseMessageType = "ErrorMessage"
	StringErrorResponseMessage       ErrorResponseMessageType = "string"
)

// IsErrorMessage reports whether ErrorResponseMessage is ErrorMessage.
func (s ErrorResponseMessage) IsErrorMessage() bool {
	return s.Type == ErrorMessageErrorResponseMessage
}

// IsString reports whether ErrorResponseMessage is string.
func (s ErrorResponseMessage) IsString() bool { return s.Type == StringErrorResponseMessage }

// SetErrorMessage sets ErrorResponseMessage to ErrorMessage.
func (s *ErrorResponseMessage) SetErrorMessage(v ErrorMessage) {
	s.Type = ErrorMessageErrorResponseMessage
	s.ErrorMessage = v
}

// GetErrorMessage returns ErrorMessage and true boolean if ErrorResponseMessage is ErrorMessage.
func (s ErrorResponseMessage) GetErrorMessage() (v ErrorMessage, ok bool) {
	if !s.IsErrorMessage() {
		return v, false
	}
	return s.ErrorMessage, true
}

// NewErrorMessageErrorResponseMessage returns new ErrorResponseMessage from ErrorMessage.
func NewErrorMessageErrorResponseMessage(v ErrorMessage) ErrorResponseMessage {
	var s ErrorResponseMessage
	s.SetErrorMessage(v)
	return s
}

// SetString sets ErrorResponseMessage to string.
func (s *ErrorResponseMessage) SetString(v string) {
	s.Type = StringErrorResponseMessage
	s.String = v
}

// GetString returns string and true boolean if ErrorResponseMessage is string.
func (s ErrorResponseMessage) GetString() (v string, ok bool) {
	if !s.IsString() {
		return v, false
	}
	return s.String, true
}

// NewStringErrorResponseMessage returns new ErrorResponseMessage from string.
func NewStringErrorResponseMessage(v string) ErrorResponseMessage {
	var s ErrorResponseMessage
	s.SetString(v)
	return s
}

