// Search results.
// Ref: #/components/schemas/InvoiceBasicInfo
type InvoiceBasicInfo struct {
	// Unique identifier of the invoice.
	ID OptInt `json:"id"`
	// Business partner id. Used to link the invoice to a customer or supplier in the business partner
	// register.
	PartnerId OptNilInt `json:"partnerId"`
	// Invoice type.
	Type OptInvoiceBasicInfoType `json:"type"`
	// Invoice status.
	Status OptInvoiceBasicInfoStatus `json:"status"`
	// Invoice number generated by Procountor.
	InvoiceNumber OptInt `json:"invoiceNumber"`
	// Invoice number from the biller in an external system.
	OriginalInvoiceNumber OptString `json:"originalInvoiceNumber"`
	// Channel of distribution for the invoice.
	InvoiceChannel OptInvoiceBasicInfoInvoiceChannel `json:"invoiceChannel"`
	// Invoice date. This is synonymous to billing date.
	Date OptDate `json:"date"`
	// Invoice payment due date.
	DueDate OptDate `json:"dueDate"`
	// Invoice payment new due date.
	NewDueDate OptDate `json:"newDueDate"`
	// Creation timestamp of the invoice. Automatically generated by Procountor.
	Created OptDateTime `json:"created"`
	// Invoice version timestamp. Automatically generated by Procountor and updated every time the
	// invoice is modified.
	Version OptDateTime `json:"version"`
	// Invoice sum info. If the invoice has currency other than the one set for the environment, it
	// returns sum for both the accounting and invoice currency.
	InvoiceSumInfo []InvoiceSumInfo `json:"invoiceSumInfo"`
	// Invoice owner's user ID.
	CreatorId    OptInt       `json:"creatorId"`
	CounterParty CounterParty `json:"counterParty"`
}

