// The address where the invoice should be sent. If omitted for sales invoice, assumed to equal the
// counter party address. If billing address is not needed for sales invoice, please send an empty
// value: billingAddress:{}. Note: For purchase invoice and purchase order, this is a billing
// delivery address and corresponds to the ”Buyer delivery address” section on UI.
// Ref: #/components/schemas/InvoiceBillingAddress
type InvoiceBillingAddress struct {
	// Name ("first line") in the address.
	Name OptString `json:"name"`
	// Specifier, such as c/o address.
	Specifier OptString `json:"specifier"`
	// Street. Required for SALES_INVOICE and SALES_ORDER if invoicing channel is MAIL. In that case,
	// must be specified in counterPartyAddress if not specified in billingAddress. Required for
	// SALES_INVOICE if invoicing channel is ELECTRONIC_INVOICE. In that case, must be specified in
	// billingAddress and counterPartyAddress.
	Street OptString `json:"street"`
	// Zip code. Required for SALES_INVOICE and SALES_ORDER if invoicing channel is MAIL. In that case,
	// must be specified in counterPartyAddress if not specified in billingAddress. Required for
	// SALES_INVOICE if invoicing channel is ELECTRONIC_INVOICE. In that case, must be specified in
	// billingAddress and counterPartyAddress.
	Zip OptString `json:"zip"`
	// City. Required for SALES_INVOICE and SALES_ORDER if invoicing channel is MAIL. In that case, must
	// be specified in counterPartyAddress if not specified in billingAddress. Required for SALES_INVOICE
	// if invoicing channel is ELECTRONIC_INVOICE. In that case, must be specified in billingAddress and
	// counterPartyAddress.
	City OptString `json:"city"`
	// Country.
	Country OptString `json:"country"`
	// Subdivision of the city.
	Subdivision OptString `json:"subdivision"`
}

