// Ref: #/components/schemas/LedgerReceipt
type LedgerReceipt struct {
	// Unique identifier of the ledger receipt. Generated by Procountor and present in the object
	// returned.
	ID OptInt `json:"id"`
	// Ledger receipt type. Use JOURNAL for creating ledger receipts (vouchers) containing ledger
	// transactions without linkage to pre-existing resources. Other types are automatically generated by
	// Procountor for holding accounting information for e.g. invoices. Types allowed for POST = JOURNAL.
	// Types allowed for PUT = JOURNAL, SALES_INVOICE, PURCHASE_INVOICE, TRAVEL_INVOICE, BILL_OF_CHARGES
	// Types allowed for GET listed below.
	Type LedgerReceiptType `json:"type"`
	// Ledger receipt status. Status of a ledger receipt equals the status of the linked invoice. All
	// ledger receipts are initially created with status UNFINISHED. For journals, possible statuses are
	// UNFINISHED, APPROVED and INVALIDATED. Ledger receipt statuses cannot be directly modified through
	// the API.
	Status OptLedgerReceiptStatus `json:"status"`
	// Ledger receipt name.
	Name OptString `json:"name"`
	// Ledger receipt date. Must not be in a closed fiscal period. See GET /fiscalyears for a list of
	// fiscal years.
	ReceiptDate time.Time `json:"receiptDate"`
	// Ledger receipt VAT type.
	VatType OptLedgerReceiptVatType `json:"vatType"`
	// Ledger receipt VAT status. This can be overridden on transaction level. Use here the numeric parts
	// of VAT status codes listed in "VAT defaults" in Procountor. For example, for VAT status code
	// "vat_12", use value 12. The VAT status used must be enabled for the current receipt type
	// (sales/purchase).
	VatStatus OptInt `json:"vatStatus"`
	// Ledger receipt VAT country. Only for JOURNAL types of ledger receipts. Requires a special right
	// for foreign VATs. See Address.country in POST /invoices for a list of allowable values.
	VatProcessing OptString `json:"vatProcessing"`
	// ID of the linked invoice. For sales and purchase invoice ledger receipts, this refers to the
	// invoice the receipt holds accounting data for. For journal receipts, an invoice is automatically
	// generated to store certain data fields. Use this ID in POST /attachments endpoint.
	InvoiceId OptNilInt `json:"invoiceId"`
	// Number of the ledger receipt.
	ReceiptNumber OptInt `json:"receiptNumber"`
	// Invoice notes. Linked to Invoice.notes. Not visible on ledger receipt printouts. Use as line break.
	//  Max length 10000.
	InvoiceNotes OptString `json:"invoiceNotes"`
	// Number of the linked invoice. Automatically generated by Procountor.
	InvoiceNumber OptInt `json:"invoiceNumber"`
	// Notes made by the accountant. Visible on ledger receipt printouts.
	AccountantsNotes OptString `json:"accountantsNotes"`
	// Transaction description. This is a summary description for any transactions belonging to the
	// ledger receipt.
	TransactionDescription OptString `json:"transactionDescription"`
	// Receipt validity time.
	ReceiptValidity OptLedgerReceiptReceiptValidity `json:"receiptValidity"`
	// Start date of the receipt period. If set, must precede the end date of the period.
	PeriodStartDate OptDate `json:"periodStartDate"`
	// End date of the receipt period. If this and the start date are set, this must be after the start
	// date.
	PeriodEndDate OptDate `json:"periodEndDate"`
	// Partner code. Identifier for the related company or person. May represent a business ID, national
	// identification number (HETU in Finland) or an account number, depending on the receipt type.
	PartnerCode  OptString       `json:"partnerCode"`
	SerialNumber OptSerialNumber `json:"serialNumber"`
	// Ledger receipt version timestamp. Automatically generated by Procountor and updated every time the
	// receipt is modified. When using PUT /ledgerreceipts, it is required to include the latest version
	// timestamp of the receipt to the request. This prevents conflicts if the receipt is being modified
	// from several sources.
	Version OptDateTime `json:"version"`
	// Accounting depreciation method for the receipt.
	Depreciation OptLedgerReceiptDepreciation `json:"depreciation"`
	// VAT date to be used if payment based VAT is enabled.
	VatDate OptDate `json:"vatDate"`
	// List containing transactions on the receipt. At least one transaction must be provided.
	Transactions []Transaction `json:"transactions"`
	// List of attachments added to this receipt. Use POST and DELETE /attachments to add and delete
	// attachments.
	Attachments []Attachment `json:"attachments"`
}

