// Invoice payment info. Includes the bank account to which the invoice should be paid, how it should
// be paid and when it should be paid.
// Ref: #/components/schemas/PaymentInfo
type PaymentInfo struct {
	// Payment method. Methods other than BANK_TRANSFER, CASH, CLEARING may require fields not supported
	// by the API. The DIRECT_DEBIT method is not supported by POST /invoices and PUT /invoices endpoints.
	//  The DKLMPKRE method is deprecated and read only, DOMESTIC_PAYMENT_CREDITOR should be used instead.
	PaymentMethod OptPaymentInfoPaymentMethod `json:"paymentMethod"`
	// Currency of the payment in ISO 4217 format.
	Currency    string         `json:"currency"`
	BankAccount OptBankAccount `json:"bankAccount"`
	// Payment due date. The payment term can be 0-999 days.
	DueDate time.Time `json:"dueDate"`
	// Payment new due date.
	NewDueDate OptDate `json:"newDueDate"`
	// Currency exchange rate. Calculated as the amount of one unit of domestic currency in foreign
	// currency. Only foreign currency payments should have a value other than 1.
	CurrencyRate float64 `json:"currencyRate"`
	// Discount percentage set in term of payment. Determines the discount if the invoice is paid before
	// due date.
	PaymentTermPercentage OptFloat64      `json:"paymentTermPercentage"`
	CashDiscount          OptCashDiscount `json:"cashDiscount"`
	// Payment reference code. If specified, must be a valid reference code where the last digit is a
	// check digit. If the field is given an empty string value, a reference code is automatically
	// generated by Procountor. If the field is not provided at all, no reference code will be assigned
	// to the invoice.
	BankReferenceCode OptString `json:"bankReferenceCode"`
	// Reference code generation type. If type not allowed for a user country will be given, then 400 is
	// returned.
	BankReferenceCodeType OptPaymentInfoBankReferenceCodeType `json:"bankReferenceCodeType"`
	// Receiver bank's clearing code for foreign payments.
	ClearingCode OptString `json:"clearingCode"`
}

