// List containing transactions on the receipt. At least one transaction must be provided.
// Ref: #/components/schemas/Transaction
type Transaction struct {
	// Unique identifier for the ledger transaction. Automatically generated by Procountor and present in
	// the object returned.
	ID OptInt `json:"id"`
	// Transaction type. Depends on the transaction and the ledger account in question. Type
	// REVERSING_ENTRY is used to indicate the first row of a ledger receipt for a specific logic on the
	// UI. Typically, it represents a transaction for a balance sheet account. Note that ledger receipts
	// with no transactions marked as reversing entries are possible. Type ENTRY is the general type for
	// transactions. It can be used even on the first rows of ledger receipts. Type RECONCILIATION_ENTRY
	// is used for getting the sum of transactions on a receipt to reconcile (to equal zero). Generally,
	// all ledger receipts should reconcile. Procountor can create reconciliation entries automatically
	// for ledger receipts when "createReconciliation=true" query parameter is specified. If VAT is used,
	// a reconciliation row might be necessary due to remainders and rounding. For both REVERSING_ENTRY
	// and RECONCILIATION_ENTRY transactions, vatStatus cannot be defined and vatPercent must be 0.
	// Additionally, a ledger can have maximum of one REVERSING_ENTRY and maximum of one
	// RECONCILIATION_ENTRY transaction. Transactions of these types cannot be removed from a ledger
	// receipt using UI once created.
	TransactionType TransactionTransactionType `json:"transactionType"`
	// Ledger account number for the transaction. Must be valid for the current Procountor environment.
	// Use GET /coa to obtain the chart of accounts.
	Account string `json:"account"`
	// Transaction accounting value. This value is net. It will be automatically rounded up to scale 2.
	AccountingValue float64 `json:"accountingValue"`
	// Transaction VAT percentage. Must be a percentage currently in use for the company.
	VatPercent OptFloat64 `json:"vatPercent"`
	// Transaction VAT type.
	VatType OptTransactionVatType `json:"vatType"`
	// Transaction VAT status. This overrides the VAT status set for the parent ledger receipt. Use here
	// the numeric parts of VAT status codes listed in "VAT defaults" in Procountor. For example, for VAT
	// status code "vat_12", use value 12. The VAT status used must be enabled for the current receipt
	// type (sales/purchase).
	VatStatus OptInt `json:"vatStatus"`
	// Transaction description. Visible on ledger receipt printouts.
	Description OptString `json:"description"`
	// Transaction balance code. Only available if the use balance sheet setting is enabled.
	BalanceCode OptString `json:"balanceCode"`
	// List of allocation ids related to the transaction.
	Allocations []int `json:"allocations"`
	// Technical ID for the partner. Can be provided in Norwegian environments only. The given partner id
	// must match a partner of type different than PERSON, existing in the current Procountor environment.
	PartnerId OptNilInt `json:"partnerId"`
	// Values of dimension items associated with this transaction. The number of provided dimension items
	// must be within the dimension max count defined by the purchased Procountor license. Provided
	// dimension pairs (dimension id - item id) must be unique within the list provided.
	DimensionItemValues []DimensionItemValue `json:"dimensionItemValues"`
	// VAT deduction percentage for the transaction.
	VatDeductionPercent OptFloat64 `json:"vatDeductionPercent"`
	// Start date of accrual/delivery periods of transaction.
	StartDate OptDate `json:"startDate"`
	// End date of accrual/delivery periods of transaction.
	EndDate OptDate `json:"endDate"`
}

